import React, { useState, useEffect, useContext } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { ProgressContext } from '../contexts/ProgressContext';
import Icon from '../components/AppIcon';

const SearchResults = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const query = searchParams.get('q') || '';
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [sortBy, setSortBy] = useState('relevance'); // 'relevance', 'progress', 'difficulty', 'alphabetical'
  const [filterBy, setFilterBy] = useState('all'); // 'all', 'completed', 'in-progress', 'not-started'
  const [subjectFilter, setSubjectFilter] = useState('all');
  const [difficultyFilter, setDifficultyFilter] = useState('all');
  const [searchHistory, setSearchHistory] = useState([]);
  const [showFilters, setShowFilters] = useState(false);
  
  const { learningNodes } = useContext(ProgressContext) || {};

  // Load search history from localStorage
  useEffect(() => {
    try {
      const history = localStorage.getItem('searchHistory');
      if (history) {
        setSearchHistory(JSON.parse(history));
      }
    } catch (error) {
      console.error('Error loading search history:', error);
    }
  }, []);

  // Save search to history
  const saveSearchToHistory = (searchQuery) => {
    if (!searchQuery.trim()) return;
    
    try {
      const newHistory = [searchQuery, ...searchHistory.filter(h => h !== searchQuery)].slice(0, 10);
      setSearchHistory(newHistory);
      localStorage.setItem('searchHistory', JSON.stringify(newHistory));
    } catch (error) {
      console.error('Error saving search history:', error);
    }
  };

  // Enhanced search with filters and sorting
  const performSearch = (searchQuery) => {
    if (!searchQuery || !learningNodes) {
      setResults([]);
      return;
    }

    // Basic search - filter by query
    let searchResults = learningNodes.filter(node =>
      node.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      node.subject.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (node.description && node.description.toLowerCase().includes(searchQuery.toLowerCase()))
    );

    // Apply subject filter
    if (subjectFilter !== 'all') {
      searchResults = searchResults.filter(node => node.subject === subjectFilter);
    }

    // Apply difficulty filter
    if (difficultyFilter !== 'all') {
      searchResults = searchResults.filter(node => node.difficulty === difficultyFilter);
    }

    // Apply completion filter
    if (filterBy !== 'all') {
      searchResults = searchResults.filter(node => {
        if (filterBy === 'completed') return node.completed;
        if (filterBy === 'in-progress') return node.progress > 0 && !node.completed;
        if (filterBy === 'not-started') return node.progress === 0;
        return true;
      });
    }

    // Apply sorting
    searchResults.sort((a, b) => {
      switch (sortBy) {
        case 'progress':
          return b.progress - a.progress;
        case 'difficulty':
          const difficultyOrder = { 'beginner': 1, 'intermediate': 2, 'advanced': 3 };
          return difficultyOrder[a.difficulty] - difficultyOrder[b.difficulty];
        case 'alphabetical':
          return a.title.localeCompare(b.title);
        case 'relevance':
        default:
          // Score based on title match vs description match
          const aScore = a.title.toLowerCase().includes(searchQuery.toLowerCase()) ? 2 : 1;
          const bScore = b.title.toLowerCase().includes(searchQuery.toLowerCase()) ? 2 : 1;
          return bScore - aScore;
      }
    });

    setResults(searchResults);
  };

  useEffect(() => {
    if (query && learningNodes) {
      setLoading(true);
      saveSearchToHistory(query);
      
      // Simulate search with a small delay
      setTimeout(() => {
        performSearch(query);
        setLoading(false);
      }, 300);
    } else {
      setResults([]);
    }
  }, [query, learningNodes, sortBy, filterBy, subjectFilter, difficultyFilter]);

  const handleNodeClick = (nodeId) => {
    navigate(`/interactive-learning-session/${nodeId}`);
  };

  const getSubjectColor = (subject) => {
    const colors = {
      mathematics: '#3b82f6',
      programming: '#10b981',
      history: '#f59e0b',
      science: '#8b5cf6',
      geography: '#06b6d4',
      literature: '#ec4899'
    };
    return colors[subject] || '#6b7280';
  };

  const getUniqueSubjects = () => {
    if (!learningNodes) return [];
    return [...new Set(learningNodes.map(node => node.subject))];
  };

  const handleSearchFromHistory = (historyQuery) => {
    setSearchParams({ q: historyQuery });
  };

  const clearSearchHistory = () => {
    setSearchHistory([]);
    localStorage.removeItem('searchHistory');
  };

  return (
    <div className="min-h-screen bg-background pt-20 px-4">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-2xl font-heading font-bold text-text-primary mb-2">
            Search Results
          </h1>
          {query && (
            <p className="text-text-secondary">
              Results for "<span className="font-medium text-text-primary">{query}</span>"
              {!loading && ` (${results.length} found)`}
            </p>
          )}
        </div>

        {/* Search Controls */}
        <div className="mb-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            {/* Sort and Filter Controls */}
            <div className="flex flex-wrap items-center gap-3">
              {/* Sort Dropdown */}
              <div className="flex items-center gap-2">
                <label className="text-sm font-medium text-text-secondary">Sort by:</label>
                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value)}
                  className="text-sm border border-border rounded-lg px-3 py-1 bg-surface text-text-primary focus:ring-2 focus:ring-primary focus:border-primary"
                >
                  <option value="relevance">Relevance</option>
                  <option value="alphabetical">Alphabetical</option>
                  <option value="progress">Progress</option>
                  <option value="difficulty">Difficulty</option>
                </select>
              </div>

              {/* Filter Toggle */}
              <button
                onClick={() => setShowFilters(!showFilters)}
                className={`flex items-center gap-2 px-3 py-1 rounded-lg text-sm font-medium transition-colors ${
                  showFilters
                    ? 'bg-primary text-white'
                    : 'bg-surface border border-border text-text-primary hover:bg-surface-50'
                }`}
              >
                <Icon name="Filter" size={16} />
                Filters
              </button>
            </div>

            {/* Results Count */}
            {query && !loading && (
              <div className="text-sm text-text-secondary">
                {results.length} result{results.length !== 1 ? 's' : ''} found
              </div>
            )}
          </div>

          {/* Expanded Filter Options */}
          {showFilters && (
            <div className="mt-4 p-4 bg-surface border border-border rounded-lg">
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {/* Subject Filter */}
                <div>
                  <label className="block text-sm font-medium text-text-primary mb-2">Subject</label>
                  <select
                    value={subjectFilter}
                    onChange={(e) => setSubjectFilter(e.target.value)}
                    className="w-full text-sm border border-border rounded-lg px-3 py-2 bg-background text-text-primary focus:ring-2 focus:ring-primary focus:border-primary"
                  >
                    <option value="all">All Subjects</option>
                    {getUniqueSubjects().map(subject => (
                      <option key={subject} value={subject}>
                        {subject.charAt(0).toUpperCase() + subject.slice(1)}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Difficulty Filter */}
                <div>
                  <label className="block text-sm font-medium text-text-primary mb-2">Difficulty</label>
                  <select
                    value={difficultyFilter}
                    onChange={(e) => setDifficultyFilter(e.target.value)}
                    className="w-full text-sm border border-border rounded-lg px-3 py-2 bg-background text-text-primary focus:ring-2 focus:ring-primary focus:border-primary"
                  >
                    <option value="all">All Levels</option>
                    <option value="beginner">Beginner</option>
                    <option value="intermediate">Intermediate</option>
                    <option value="advanced">Advanced</option>
                  </select>
                </div>

                {/* Progress Filter */}
                <div>
                  <label className="block text-sm font-medium text-text-primary mb-2">Progress</label>
                  <select
                    value={filterBy}
                    onChange={(e) => setFilterBy(e.target.value)}
                    className="w-full text-sm border border-border rounded-lg px-3 py-2 bg-background text-text-primary focus:ring-2 focus:ring-primary focus:border-primary"
                  >
                    <option value="all">All Topics</option>
                    <option value="not-started">Not Started</option>
                    <option value="in-progress">In Progress</option>
                    <option value="completed">Completed</option>
                  </select>
                </div>
              </div>

              {/* Clear Filters */}
              <div className="mt-4 flex justify-end">
                <button
                  onClick={() => {
                    setSortBy('relevance');
                    setFilterBy('all');
                    setSubjectFilter('all');
                    setDifficultyFilter('all');
                  }}
                  className="text-sm text-primary hover:text-primary-700 font-medium"
                >
                  Clear all filters
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Search History - shown when no query */}
        {!query && !loading && searchHistory.length > 0 && (
          <div className="mb-8">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-text-primary">Recent Searches</h3>
              <button
                onClick={clearSearchHistory}
                className="text-sm text-text-secondary hover:text-text-primary"
              >
                Clear all
              </button>
            </div>
            <div className="flex flex-wrap gap-2">
              {searchHistory.map((historyQuery, index) => (
                <button
                  key={index}
                  onClick={() => handleSearchFromHistory(historyQuery)}
                  className="px-3 py-1 bg-surface border border-border rounded-full text-sm text-text-primary hover:bg-surface-50 hover:border-primary transition-colors"
                >
                  <Icon name="Clock" size={14} className="inline mr-1" />
                  {historyQuery}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Loading State */}
        {loading && (
          <div className="flex items-center justify-center py-12">
            <div className="flex items-center space-x-3">
              <div className="w-6 h-6 border-2 border-primary border-t-transparent rounded-full animate-spin"></div>
              <span className="text-text-secondary">Searching...</span>
            </div>
          </div>
        )}

        {/* No Query */}
        {!query && !loading && (
          <div className="text-center py-12">
            <Icon name="Search" size={48} className="text-text-secondary mx-auto mb-4" />
            <h2 className="text-xl font-medium text-text-primary mb-2">Search Learning Content</h2>
            <p className="text-text-secondary">Enter a search term to find topics, subjects, or sessions.</p>
          </div>
        )}

        {/* No Results */}
        {query && !loading && results.length === 0 && (
          <div className="text-center py-12">
            <Icon name="SearchX" size={48} className="text-text-secondary mx-auto mb-4" />
            <h2 className="text-xl font-medium text-text-primary mb-2">No Results Found</h2>
            <p className="text-text-secondary mb-4">
              We couldn't find any content matching "{query}"
            </p>
            <button
              onClick={() => navigate('/adaptive-learning-dashboard')}
              className="bg-primary text-white px-4 py-2 rounded-lg font-medium hover:bg-primary-700 transition-colors"
            >
              Browse All Topics
            </button>
          </div>
        )}

        {/* Results */}
        {!loading && results.length > 0 && (
          <div className="space-y-4">
            {results.map((node) => (
              <div
                key={node.id}
                onClick={() => handleNodeClick(node.id)}
                className="bg-surface border border-border rounded-lg p-6 cursor-pointer hover:shadow-warm-md transition-all duration-200 hover:border-primary"
              >
                <div className="flex items-start space-x-4">
                  {/* Subject Icon */}
                  <div
                    className="w-12 h-12 rounded-lg flex items-center justify-center flex-shrink-0"
                    style={{ backgroundColor: getSubjectColor(node.subject) + '15' }}
                  >
                    <span
                      className="text-lg font-semibold"
                      style={{ color: getSubjectColor(node.subject) }}
                    >
                      {node.subject[0].toUpperCase()}
                    </span>
                  </div>

                  {/* Content */}
                  <div className="flex-1">
                    <div className="flex items-start justify-between mb-2">
                      <h3 className="text-lg font-semibold text-text-primary hover:text-primary transition-colors">
                        {node.title}
                      </h3>
                      <div className="flex items-center space-x-2">
                        {/* Difficulty Badge */}
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                          node.difficulty === 'beginner' ? 'bg-green-100 text-green-800' :
                          node.difficulty === 'intermediate' ? 'bg-yellow-100 text-yellow-800' :
                          'bg-red-100 text-red-800'
                        }`}>
                          {node.difficulty}
                        </span>
                        
                        {/* Progress Badge */}
                        {node.progress > 0 && (
                          <span className="px-2 py-1 bg-blue-100 text-blue-800 rounded-full text-xs font-medium">
                            {Math.round(node.progress)}% complete
                          </span>
                        )}
                      </div>
                    </div>

                    <p className="text-text-secondary text-sm mb-3 capitalize">
                      {node.subject} • {node.estimatedTime || '30 min'}
                    </p>

                    {node.description && (
                      <p className="text-text-secondary text-sm leading-relaxed">
                        {node.description}
                      </p>
                    )}

                    {/* Progress Bar */}
                    {node.progress > 0 && (
                      <div className="mt-3">
                        <div className="w-full bg-surface-100 rounded-full h-2">
                          <div
                            className="h-2 rounded-full bg-primary transition-all duration-300"
                            style={{ width: `${node.progress}%` }}
                          ></div>
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Arrow */}
                  <Icon name="ChevronRight" size={20} className="text-text-secondary" />
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Back to Dashboard */}
        <div className="mt-8 text-center">
          <button
            onClick={() => navigate('/adaptive-learning-dashboard')}
            className="text-primary hover:text-primary-700 font-medium transition-colors"
          >
            ← Back to Dashboard
          </button>
        </div>
      </div>
    </div>
  );
};

export default SearchResults;